    ld.param.u32 %len_out,  [param_len_out];
    ld.param.u32 %ksize,    [param_ksize];
    ld.param.u32 %stride,   [param_stride];
    ld.param.u32 %dilation, [param_dilation];

    // Guard against threads beyond out_ch
    setp.ge.u32 p0, %tid_x, %out_ch;
    @p0 bra DONE;

    // Registers for accumulation
    .reg .f32   %acc;
    mov.f32 %acc, 0f00000000;          // 0.0f

    // Compute constant offsets (byte based, fp16 = 2 bytes)
    .reg .u64   %byte2;
    mov.u64 %byte2, 2;

