    // wgt_index = ((out_c * in_ch + ic) * ksize) + k
    .reg .u64 %wgt_idx;
    mul.lo.u32 %tmp32, %tid_x, %in_ch;          // out_c * in_ch
    add.u32 %tmp32, %tmp32, %ic;                // + ic
    mul.lo.u64 %wgt_idx, %tmp32, %ksize;        // * ksize
    add.u64 %wgt_idx, %wgt_idx, %k;             // + k
    mul.lo.u64 %wgt_idx, %wgt_idx, %byte2;      // convert to bytes

    // ---- Load fp16 values ----
