    cvt.rn.f32.f16 %inp_f32, %inp_f16;
    cvt.rn.f32.f16 %wgt_f32, %wgt_f16;
    mul.f32 %prod, %inp_f32, %wgt_f32;
    add.f32 %acc, %acc, %prod;

