    setp.eq.u64 p3, %bias_ptr, 0;
    @p3 bra STORE;

    // load bias[out_c]
    .reg .f16 %bias_f16;
    .reg .u64 %bias_off;
    mul.lo.u64 %bias_off, %tid_x, %byte2;
    ld.global.f16 %bias_f16, [%bias_ptr + %bias_off];
    .reg .f32 %bias_f32;
    cvt.rn.f32.f16 %bias_f32, %bias_f16;
    add.f32 %acc, %acc, %bias_f32;

