    mul.lo.u64 %out_idx, %tmp32, %len_out;       // * len_out
    mul.lo.u32 %tmp32, %bid_y, %byte2;           // out_pos *2
    add.u64 %out_idx, %out_idx, %tmp32;          // final byte offset

    st.global.f16 [%out_ptr + %out_idx], %out_f16;

DONE:
    ret;
