    def __init__(self, weight: torch.Tensor, bias: torch.Tensor = None,
                 stride: int = 1, dilation: int = 1):
        """
        weight: Tensor of shape (out_channels, in_channels, kernel_size) dtype float16, CUDA.
        bias:   Tensor of shape (out_channels,) dtype float16, CUDA, or None.
